var e={configTemplates:{intro:{t:0,b:{t:2,i:[{t:3}],s:`Yapıştırmaya hazır Klipper yapılandırma blokları ve makroları - başlangıç dizileri, filament işleme, input shaping, tabla ağı ve daha fazlası. Birini kopyalayın ve printer.cfg'nize bırakın (Yapılandırma Düzenleyici onu yapıştırmak için iyi bir yerdir).`}},help:{guide:{t:0,b:{t:2,i:[{t:3}],s:`Yardım`}},guideTitle:{t:0,b:{t:2,i:[{t:3}],s:`Yapılandırma Şablonları Hakkında`}},close:{t:0,b:{t:2,i:[{t:3}],s:`Kapat`}},howToRead:{t:0,b:{t:2,i:[{t:3}],s:`Nasıl kullanılır`}},steps:[{t:0,b:{t:2,i:[{t:3}],s:`Bir makro veya yapılandırma bloğu bulmak için kategoriye göre filtreleyin.`}},{t:0,b:{t:2,i:[{t:3}],s:`Açıklamayı ve hangi bölümlere ihtiyaç duyduğunu okuyun.`}},{t:0,b:{t:2,i:[{t:3}],s:`Şablonu kopyalayın, yapılandırmanıza yapıştırın ve değerleri ayarlayın.`}}],topics:{what:{title:{t:0,b:{t:2,i:[{t:3}],s:`Bunlar nedir`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Yaygın Klipper yapı taşlarından oluşan derli toplu bir set: gcode_macro'lar (PRINT_START, PAUSE/RESUME, filament yükle/boşalt, M600) ve yapılandırma bölümleri ([input_shaper], [bed_mesh], [firmware_retraction], …). Bunlar başlangıç noktalarıdır - her birini okuyun ve makineniz için ayarlayın.`}}},insert:{title:{t:0,b:{t:2,i:[{t:3}],s:`Bir şablon ekleme`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Bir şablonu kopyalayın, ardından printer.cfg'nize yapıştırın - Yapılandırma Düzenleyici'nin Ham görünümü uygun bir yerdir. Kaydettikten sonra bir firmware yeniden başlatması onu uygular. Değerleri her zaman önce inceleyin; buradaki varsayılanlar makul ama yazıcınıza göre ayarlanmamıştır.`}}},sections:{title:{t:0,b:{t:2,i:[{t:3}],s:`Gerekli bölümler`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Her şablon, tanımladığı veya bağlı olduğu yapılandırma bölümlerini listeler. Bir bölüm yapılandırmanızda zaten varsa, bir kopyasını yapıştırmak yerine anahtarları birleştirin (yinelenen bir bölüm başlangıçta reddedilir).`}}},glossary:{title:{t:0,b:{t:2,i:[{t:3}],s:`Sözlük`}},body:{t:0,b:{static:``,t:2,i:[]}}}},glossary:{template:{term:{t:0,b:{t:2,i:[{t:3}],s:`Şablon`}},def:{t:0,b:{t:2,i:[{t:3}],s:`printer.cfg'ye kopyaladığınız, yapıştırmaya hazır bir Klipper yapılandırma veya makro G-code parçası.`}}},macro:{term:{t:0,b:{t:2,i:[{t:3}],s:`gcode_macro`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Yapılandırmada tanımladığınız (ör. PRINT_START) ve bir G-code dizisini çalıştıran adlandırılmış bir komut.`}}},section:{term:{t:0,b:{t:2,i:[{t:3}],s:`Bölüm`}},def:{t:0,b:{t:2,i:[{t:3}],s:`[köşeli parantezli] bir yapılandırma bloğu, ör. [bed_mesh] - Klipper yapılandırmasının gruplandığı birim.`}}}}},category:{label:{t:0,b:{t:2,i:[{t:3}],s:`Kategori`}},all:{t:0,b:{t:2,i:[{t:3}],s:`Tüm kategoriler`}}},template:{copy:{t:0,b:{t:2,i:[{t:3}],s:`Kopyala`}},copied:{t:0,b:{t:2,i:[{t:3}],s:`Kopyalandı!`}},requires:{t:0,b:{t:2,i:[{t:3,v:`Bölümler: `},{t:4,k:`sections`}]}},requiresNone:{t:0,b:{t:2,i:[{t:3}],s:`-`}}},count:{t:0,b:{t:2,i:[{t:4,k:`n`},{t:3,v:` şablon`}]}},states:{loading:{t:0,b:{t:2,i:[{t:3}],s:`Şablonlar yükleniyor…`}},error:{t:0,b:{t:2,i:[{t:3}],s:`Şablonlar yüklenemedi.`}},empty:{t:0,b:{t:2,i:[{t:3}],s:`Bu kategoride şablon yok.`}},retry:{t:0,b:{t:2,i:[{t:3}],s:`Yeniden dene`}}},categories:{config_blocks:{t:0,b:{t:2,i:[{t:3}],s:`Yapılandırma blokları`}},macros:{t:0,b:{t:2,i:[{t:3}],s:`Makrolar`}}}}};export{e as default};